import { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, PointLight, Color } from 'three/webgpu';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, smoothstep, fract, sin, dot, vec2, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new Group();
  root.name = 'pricing-card-3';

  const palette = (config.intent?.visualSpec?.colors) ?? config.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- geometry sizing (source rect 512x320 -> 1.6:1 aspect) ----
  const cardWidth = 2.0;
  const cardHeight = cardWidth / 1.6;

  const disposables = [];
  const timelines = [];

  // ---- drop-shadow plane (depth plane 1) ----
  const shadowGeo = new PlaneGeometry(cardWidth * 1.35, cardHeight * 1.5);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true });
  const sUv = uv();
  const sFall = smoothstep(0.5, 0.0, sUv.distance(vec2(0.5, 0.5)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = sFall.mul(0.45);
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0.08, -0.1, -0.06);
  root.add(shadowMesh);
  disposables.push(shadowGeo, shadowMat);

  // ---- engineered gradient backing plate (depth plane 2) ----
  const plateDepth = 0.05;
  const plateGeo = new BoxGeometry(cardWidth + 0.12, cardHeight + 0.12, plateDepth);
  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.45,
  });
  const pUv = uv();
  const gradientNode = mix(color(palette.surface), color(palette.ink), smoothstep(0.0, 1.0, pUv.y));
  const noiseSeed = dot(pUv, vec2(12.9898, 78.233));
  const grain = fract(sin(noiseSeed).mul(43758.5453));
  const grainOffset = grain.sub(0.5).mul(0.035);
  plateMat.colorNode = gradientNode.add(vec3(grainOffset, grainOffset, grainOffset));
  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0, -0.03);
  root.add(plateMesh);
  disposables.push(plateGeo, plateMat);

  // ---- accent trim strip (<=10% of frame) ----
  const trimGeo = new BoxGeometry(cardWidth * 0.42, 0.045, plateDepth + 0.01);
  const trimMat = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.3,
  });
  trimMat.colorNode = color(palette.accent);
  trimMat.emissiveNode = color(palette.accent).mul(0.65);
  const trimMesh = new Mesh(trimGeo, trimMat);
  trimMesh.position.set(-cardWidth * 0.22, -cardHeight / 2 - 0.02, 0.005);
  root.add(trimMesh);
  disposables.push(trimGeo, trimMat);

  // ---- image content plane (depth plane 3, frontmost) ----
  const imgGeo = new PlaneGeometry(cardWidth * 0.92, cardHeight * 0.86);
  const imgMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.0,
    color: new Color(palette.paper),
  });
  const imgMesh = new Mesh(imgGeo, imgMat);
  imgMesh.position.set(0, 0.01, plateDepth / 2 + 0.01);
  root.add(imgMesh);
  disposables.push(imgGeo, imgMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- local rim/accent light (metal needs something to reflect) ----
  const rimLight = new PointLight(new Color(palette.accent), 0.9, 6, 2);
  rimLight.position.set(0.9, 0.4, 1.1);
  root.add(rimLight);

  const keyFillLight = new PointLight(new Color(palette.paper), 0.5, 6, 2);
  keyFillLight.position.set(-0.6, 0.6, 1.4);
  root.add(keyFillLight);

  // ---- apply every listed cinematic primitive (none specified) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- entrance: weighted-settle ----
  root.scale.set(0.96, 0.96, 0.96);
  root.position.y += 0.3;
  const entrance = gsap.timeline();
  entrance.to(root.scale, {
    x: 1.0, y: 1.0, z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  entrance.to(root.position, {
    y: root.position.y - 0.3,
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  timelines.push(entrance);

  // ---- idle: gentle breathing (<=2%) ----
  const idle = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.9 });
  idle.to(plateMesh.scale, {
    x: 1.02, y: 1.02, z: 1.0,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(idle);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const h of primitiveHandles) {
      h.cleanup?.();
    }
    root.remove(rimLight);
    root.remove(keyFillLight);
    for (const d of disposables) {
      d.dispose?.();
    }
    if (imgMat.map) imgMat.map.dispose?.();
  };

  return root;
}
